26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE = 0.1;
28	const CURSE_SURCHARGE = 0.5;
29	const HIGH_ENCHANTMENT_THRESHOLD = 5;
30	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
31	const LOYALTY_YEARS_THRESHOLD = 2;
32	const LOYALTY_DISCOUNT = 0.2;
33	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
34	
35	const ITEM_BASE_PREMIUMS: Record<string, number> = {
36	  sword: 100,
37	  amulet: 60,
38	  staff: 80,
39	  potion: 40,
40	  rune: 25,
41	  moonstone: 25,
42	};
43	
44	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
45	
46	const BLOCK_SIZE = 3;
47	const BLOCK_BASE_PREMIUM = 60;
48	
49	const countByType = (items: Item[]): Map<string, number> => {
50	  const counts = new Map<string, number>();
51	  for (const item of items) {
52	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
53	  }
54	  return counts;
55	};
56	
57	const basePremiumForGroup = (type: string, count: number): number =>
58	  count === BLOCK_SIZE
59	    ? BLOCK_BASE_PREMIUM
60	    : count * ITEM_BASE_PREMIUMS[type];
61	
62	const policyBasePremium = (items: Item[]): number =>
63	  [...countByType(items)].reduce(
64	    (total, [type, count]) => total + basePremiumForGroup(type, count),
65	    0,
66	  );
67	
68	type SurchargeRule = {
69	  appliesTo: (item: Item) => boolean;
70	  rate: number;
71	};
72	
73	const SURCHARGE_RULES: SurchargeRule[] = [
74	  {
75	    appliesTo: (item) => item.cursed === true,
76	    rate: CURSE_SURCHARGE,
77	  },
78	  {
79	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
80	    rate: HIGH_ENCHANTMENT_SURCHARGE,
81	  },
82	];
83	
84	const itemSurcharge = (item: Item): number => {
85	  const itemBasePremium = ITEM_BASE_PREMIUMS[item.type];
86	  return SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).reduce(
87	    (surcharge, rule) => surcharge + itemBasePremium * rule.rate,
88	    0,
89	  );
90	};
91	
92	const sumItemSurcharges = (items: Item[]): number =>
93	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
94	
95	const quotePremium = (
96	  items: Item[],
97	  customer: Customer,
98	  isFollowUpContract: boolean,
99	): number => {
100	  const base = policyBasePremium(items);
101	  const loyaltyDiscount =
102	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
103	      ? base * LOYALTY_DISCOUNT
104	      : 0;
105	  const followUpDiscount = isFollowUpContract
106	    ? base * FOLLOW_UP_CONTRACT_DISCOUNT
107	    : 0;
108	  return roundInMHPCOsFavour(
109	    base +
110	      sumItemSurcharges(items) -
111	      loyaltyDiscount -
112	      followUpDiscount +
113	      base * FIRST_INSURANCE_SURCHARGE +
114	      PROCESSING_FEE,
115	  );
116	};
117	
118	export const runScenario = (scenario: Scenario): ScenarioResults => {
119	  return {
120	    results: scenario.steps.map((step, index) => ({
121	      premium: quotePremium(step.items, scenario.customer, index > 0),
122	    })),
123	  };
124	};
