npx tsx -e '
const rates=[0.1,-0.2,-0.15];
const bases=[0,25,40,50,60,75,80,100,120,160,175,250,500,1000];
const subsets=[[0],[0,1],[0,2],[0,1,2]];
let worst=0;
for(const b of bases)for(const s of subsets){
  const nu=s.reduce((t,i)=>t+b*rates[i],0);
  let ol=b*0.1; if(s.includes(1))ol-=b*0.2; if(s.includes(2))ol-=b*0.15;
  const d=Math.abs(nu-ol); if(d>worst)worst=d;
  if(Math.ceil(b+nu+5)!==Math.ceil(b+ol+5))console.log("ROUNDING DIVERGENCE",b,s,nu,ol);
}
console.log("max modifier delta:",worst);
'
